    monkeypatch, checkpoint_heads, runtime_heads, tp_size
):
    """Each rank loads its checkpoint heads and disables only padded heads."""
    monkeypatch.setattr(
        weight_utils, "get_tensor_model_parallel_world_size", lambda: tp_size
    )
    checkpoint = torch.arange(checkpoint_heads, dtype=torch.float32)
    for tp_rank in range(tp_size):
        monkeypatch.setattr(
            weight_utils, "get_tensor_model_parallel_rank", lambda rank=tp_rank: rank
        )
        param = torch.nn.Parameter(torch.zeros(runtime_heads), requires_grad=False)
        load_attention_sink(param, checkpoint)
        local_heads = checkpoint.chunk(tp_size)[tp_rank]
        expected = torch.cat(
            (
                local_heads,
                torch.full((runtime_heads - local_heads.numel(),), -torch.inf),
            )
        )
        assert torch.equal(param, expected)", "helpers": [], "implementation_anchors": ["vllm/model_executor/model_loader/weight_utils.py:1618", "vllm/model_executor/model_loader/weight_utils.py:1634", "vllm/model_executor/model_loader/weight_utils.py:1682", "vllm/model_executor/model_loader/weight_utils.py:1772", "vllm/model_executor/layers/quantization/base_config.py:232", "vllm/model_executor/layers/quantization/base_config.py:267", "vllm/model_executor/models/utils.py:58", "vllm/model_executor/layers/layernorm.py:70", "vllm/model_executor/layers/layernorm.py:162", "vllm/model_executor/layers/layernorm.py:248", "vllm/model_executor/layers/layernorm.py:339"], "external_helper_anchors": [], "external_helper_sources": [], "validation": "仅静态源码核对，未导入或执行上游，未使用GPU"}

